<?php
require_once __DIR__.'/Icons.php';
function url(string $route,array $args=[]): string {return '?'.http_build_query(['r'=>$route]+$args);}
function linkTo(string $text,string $route,array $args=[],string $class='button secondary'): string {
 $nav=str_contains($class,'nav-link');$decorate=$nav||in_array($text,['new_record','register_student','new_enrollment','collect_payment','edit','profile','open','receipt','employee_payslip','cancel'],true);
 return '<a class="'.e($class).'" href="'.e(url($route,$args)).'"'.($nav&&str_contains($class,'active')?' aria-current="page"':'').'>'.($decorate?uiIcon($nav?$route:$text):'').'<span>'.e(t($text)).'</span></a>';
}
function formStart(string $action,array $hidden=[]): void {
 $GLOBALS['form_action']=$action;
 $token=replaying()&&preg_match('/^[a-f0-9]{64}$/D',(string)($_POST['token']??''))?$_POST['token']:token();
 echo '<form method="post" enctype="multipart/form-data" class="form-grid" data-action="'.e($action).'" data-saving="'.e(t('saving')).'"'.(in_array($action,['refund','reverse','close_enrollment','approve_payroll','revoke'],true)?' data-confirm="'.e(t('confirm_operation')).'"':'').'><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="token" value="'.e($token).'">';
 foreach($hidden as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';
}
function formEnd(string $label='save',array $next=[]): void {
 echo '<div class="form-actions"><button type="submit">'.uiIcon($label).'<span>'.e(t($label)).'</span></button>';
 foreach($next as $value=>$text)echo '<button type="submit" class="secondary" name="next_step" value="'.e($value).'">'.e(t($text)).'</button>';
 if(($GLOBALS['form_action']??'')==='save_module')echo linkTo('cancel',$_GET['r']??'dashboard');
 echo '<span class="form-progress" role="status"></span></div></form>';$GLOBALS['form_action']='';
}
function options(string $table): array {static $cache=[];return $cache[$table]??=loadOptions($table);}
function loadOptions(string $table): array {
 if($table==='class_subjects'){$sql='SELECT cs.id,CONCAT(b.name," / ",s.name," / ",t.name) name FROM class_subjects cs JOIN batches b ON b.id=cs.batch_id JOIN subjects s ON s.id=cs.subject_id JOIN teachers t ON t.id=cs.teacher_id';$args=[];if(user()['teacher_id']&&!can('*')){$sql.=' WHERE cs.teacher_id=?';$args[]=(int)user()['teacher_id'];}return q($sql.' ORDER BY b.name',$args)->fetchAll();}
 if($table==='employees')return q("SELECT id,CONCAT(name,' / ',job_title,' / ',COALESCE(public_code,id)) name FROM employees WHERE status='active' ORDER BY name")->fetchAll();
 if($table==='subjects')return q('SELECT s.id,CONCAT(COALESCE(p.name,"—")," / ",s.name) name FROM subjects s LEFT JOIN programs p ON p.id=s.program_id ORDER BY p.name,s.name')->fetchAll();
 if($table==='batches'){
  $rows=q('SELECT b.id,b.name,p.name program FROM batches b JOIN programs p ON p.id=b.program_id ORDER BY b.name')->fetchAll();
  foreach($rows as &$row){$parts=[];foreach(q('SELECT s.name subject,tt.start_time,tt.end_time,r.name room FROM class_subjects cs JOIN subjects s ON s.id=cs.subject_id LEFT JOIN timetable tt ON tt.class_subject_id=cs.id LEFT JOIN rooms r ON r.id=tt.room_id WHERE cs.batch_id=? ORDER BY tt.start_time',[$row['id']]) as $v)$parts[]=$v['subject'].($v['start_time']?' / '.substr($v['start_time'],0,5).'–'.substr($v['end_time'],0,5).' / '.$v['room']:'');$row['name']=$row['program'].' / '.$row['name'].' / '.implode('؛ ',array_unique($parts));}unset($row);return $rows;
 }
 if($table==='enrollments')return q('SELECT e.id,CONCAT("#",e.id," · ",s.name," / ",b.name) name FROM enrollments e JOIN students s ON s.id=e.student_id JOIN batches b ON b.id=e.batch_id ORDER BY e.id DESC')->fetchAll();
 $allowed=['employees','students','teachers','programs','subjects','batches','rooms','accounts','roles'];if(!in_array($table,$allowed,true))throw new LogicException('Unknown selector');return q("SELECT id,name FROM `$table` ORDER BY name")->fetchAll();
}
function field(string $key,string $type='text',$value='',bool $required=true): void {
 static $number=0;$inputId='field-'.(++$number);$replayed=replaying()&&array_key_exists($key,$_POST);$value=formValue($key,$value);
 $optional=str_starts_with($type,'?');$type=ltrim($type,'?');$required=$required&&!$optional;$req=$required?' required':'';echo '<div class="field"><label for="'.e($inputId).'">'.e(t($key==='capacity'?'seat_capacity':$key)).($required?' <small>•</small>':'').'</label>';
 if(in_array($type,['ref:batches','ref:class_subjects','ref:students','ref:enrollments','ref:receipts','ref:charges','ref:allocations','ref:payroll','ref:movements','ref:certificates'],true)){lookupField($key,substr($type,4),$value,$required,$inputId);
 }elseif(str_starts_with($type,'ref:')){$choices=options(substr($type,4));if($type==='ref:accounts'&&$required&&(string)$value===''&&count($choices)===1)$value=$choices[0]['id'];if(count($choices)>8)echo '<input class="select-search" type="search" placeholder="'.e(t('filter_options')).'" aria-label="'.e(t('filter_options')).'">';echo '<select id="'.e($inputId).'" name="'.e($key).'"'.$req.'><option value="">—</option>';foreach($choices as $o)echo '<option value="'.e($o['id']).'"'.((string)$o['id']===(string)$value?' selected':'').'>'.e($o['name']).' · #'.e($o['id']).'</option>';echo '</select>';
 }elseif(str_starts_with($type,'choice:')){echo '<select id="'.e($inputId).'" name="'.e($key).'"'.$req.'>';if(!$required)echo '<option value=""></option>';foreach(explode('|',substr($type,7)) as $o)echo '<option value="'.e($o).'"'.((string)$value===$o?' selected':'').'>'.e(t($o)).'</option>';echo '</select>';
 }elseif($type==='textarea'){echo '<textarea id="'.e($inputId).'" name="'.e($key).'" rows="3"'.$req.'>'.e($value).'</textarea>';
 }elseif($type==='date'||$type==='month'||$key==='month'||$key==='period'){
  $mode=($type==='month'||in_array($key,['month','period'],true))?'month':'date';
  if($mode==='date'&&!$replayed)$value=$value?fdate($value):($required?fdate(date('Y-m-d')):'');
  dateControl($inputId,$key,(string)$value,$mode,$required,$key==='period'?'g':cal());
 }else{$htmltype=in_array($type,['password','time','email'],true)?$type:'text';echo '<input id="'.e($inputId).'" type="'.$htmltype.'" name="'.e($key).'" value="'.e($value).'"'.$req.(in_array($type,['money','int'],true)?' inputmode="decimal" dir="ltr"':'').'>';}

 echo '</div>';
}
function panel(string $title): void {
 $secondary=['create_charge','allocate_advance','other_movement','discount','refund','reverse_movement','close_transfer','agreement','roles','revoke','new_account'];
 $details=in_array($title,$secondary,true);$GLOBALS['panel_details']=$details;
 $open=$details&&(!empty($GLOBALS['replay'])||($_GET['focus']??'')===$title);
 echo '<'.($details?'details':'section').' class="panel'.($details?' secondary-panel':'').'" id="panel-'.e($title).'"'.($open?' open':'').'>';
 echo $details?'<summary>'.e(t($title)).'<span class="muted">'.e(t('expand_action')).'</span></summary><div class="panel-body">':'<h2><span class="panel-icon">'.uiIcon($title).'</span><span>'.e(t($title)).'</span></h2>';
}
function endPanel(): void {echo !empty($GLOBALS['panel_details'])?'</div></details>':'</section>';$GLOBALS['panel_details']=false;}
function table(array $headers,array $rows): void {echo '<div class="table-wrap"><table><thead><tr>';foreach($headers as $h)echo '<th>'.e(t($h==='capacity'?'seat_capacity':$h)).'</th>';echo '</tr></thead><tbody>';if(!$rows)echo '<tr><td colspan="'.count($headers).'" class="empty">'.e(t('no_records')).'</td></tr>';foreach($rows as $row){echo '<tr>';foreach($row as $v)echo '<td>'.e($v).'</td>';echo '</tr>';}echo '</tbody></table></div>';}
function pageStart(string $title): void {
 $lang=lang();$center=setting($lang==='en'?'center_name_en':'center_name');echo '<!doctype html><html lang="'.$lang.'" dir="'.($lang==='fa'?'rtl':'ltr').'"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="icon" type="image/png" href="assets/kda-logo-book-20261031.png"><script src="assets/theme.js?v='.filemtime(dirname(__DIR__).'/public/assets/theme.js').'"></script><title>'.e(t($title).' · '.$center).'</title><link rel="stylesheet" href="assets/app.css?v='.filemtime(dirname(__DIR__).'/public/assets/app.css').'"><link rel="stylesheet" href="assets/theme.css?v='.filemtime(dirname(__DIR__).'/public/assets/theme.css').'"><link rel="stylesheet" href="assets/design.css?v='.filemtime(dirname(__DIR__).'/public/assets/design.css').'"><link rel="preload" href="assets/fonts/Vazirmatn-Variable.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/Inter-Variable.woff2" as="font" type="font/woff2" crossorigin><script defer src="assets/date-picker.js?v=1"></script><script defer src="assets/print.js?v=1"></script><script defer src="assets/app.js?v='.filemtime(dirname(__DIR__).'/public/assets/app.js').'"></script></head><body data-table-hint="'.e(t('table_scroll_hint')).'" data-failed-action="'.e(!empty($GLOBALS['replay'])?($_POST['action']??''):'').'"><a class="skip-link" href="#main-content">'.e(t('skip_content')).'</a>';
 if(user()){echo '<aside class="sidebar no-print" id="sidebar"><div class="brand"><img class="brand-logo" src="assets/kda-logo-book-20261031.png" alt="KDA" width="84" height="84"><strong>'.e($center).'</strong><small>'.e(t('offline_center')).'</small></div><nav id="main-nav" aria-label="'.e(t('menu')).'">';$lastGroup='';foreach(['dashboard'=>['dashboard',''], 'students'=>['students','students.view'],'enrollments'=>['enrollments','students.view'],'teachers'=>['teachers','academic.view'],'employees'=>['employees','employees.view'],'programs'=>['programs','academic.view'],'subjects'=>['subjects','academic.view'],'batches'=>['batches','academic.view'],'rooms'=>['rooms','academic.view'],'timetable'=>['timetable','academic.view'],'holidays'=>['holidays','academic.view'],'forms'=>['forms','print'],'attendance'=>['attendance','attendance.view'],'assessments'=>['assessments','exams.view'],'results'=>['results','exams.view'],'certificates'=>['certificates','exams.view'],'finance'=>['finance','finance.view'],'payroll'=>['payroll','payroll.view'],'employee_payroll'=>['employee_payroll','payroll.view'],'reports'=>['reports','finance.view'],'users'=>['users','users.manage'],'settings'=>['settings','settings.manage'],'backup'=>['backup','backup.manage'],'audit'=>['audit','audit.view']] as $route=>[$label,$perm]){if(user()['teacher_id']&&!can('*')&&!in_array($route,['dashboard','class_subjects','timetable','attendance','assessments','results'],true))continue;if(!$perm||can($perm)){$group=in_array($route,['dashboard','students','enrollments'],true)?'nav_daily':(in_array($route,['finance','payroll','employee_payroll','reports'],true)?'nav_finance':(in_array($route,['users','settings','backup','audit'],true)?'nav_admin':'nav_academic'));if($group!==$lastGroup){echo '<span class="nav-group">'.e(t($group)).'</span>';$lastGroup=$group;}echo linkTo($label,$route,[],'nav-link '.(($_GET['r']??'dashboard')===$route?'active':''));}}echo '</nav><div class="sidebar-foot">'.e(t('local_data')).'</div></aside>';}
 echo '<main id="main-content" class="'.(user()?'workspace':'login-wrap').'"><header class="topbar no-print"><div><button type="button" class="menu-toggle secondary" aria-controls="main-nav" aria-expanded="false" data-menu>'.e(t('menu')).'</button><span class="eyebrow">'.e(t('education_management')).'</span><h1>'.e(t($title)).'</h1></div><div class="top-actions">';
 echo '<button type="button" class="theme-toggle" data-theme-toggle data-light-label="'.e(t('light_mode')).'" data-dark-label="'.e(t('dark_mode')).'" aria-pressed="false" aria-label="'.e(t('dark_mode')).'"><svg class="theme-moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 15.5A8.5 8.5 0 0 1 8.5 4 8.5 8.5 0 1 0 20 15.5Z"/></svg><svg class="theme-sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/></svg><span data-theme-label>'.e(t('dark_mode')).'</span></button>';
 if(user()) {echo personPhoto('users',(int)user()['id']).'<span>'.e(user()['name']).'</span>';formStart('preferences');echo '<select name="lang"><option value="fa"'.(lang()==='fa'?' selected':'').'>دری</option><option value="en"'.(lang()==='en'?' selected':'').'>English</option></select><select name="calendar"><option value="j"'.(cal()==='j'?' selected':'').'>'.e(t('shamsi')).'</option><option value="g"'.(cal()==='g'?' selected':'').'>'.e(t('gregorian')).'</option></select>';formEnd('apply');formStart('logout');formEnd('logout');}
 echo '</div></header>';if(!user())echo '<div class="login-brand"><img src="assets/kda-logo-book-20261031.png" alt="KDA" width="100" height="100"><strong>'.e($center).'</strong></div>';echo '<div class="print-header"><img class="print-brand-logo" src="assets/kda-logo-book-20261031.png" alt="KDA" width="64" height="64"><h1>'.e($center).'</h1><p>'.e(setting('address').' · '.setting('phone')).'</p><h2>'.e(t($title)).'</h2></div>';
 if(isset($_SESSION['flash'])){echo '<div class="notice" role="status">'.e($_SESSION['flash']).'</div>';unset($_SESSION['flash']);}
 if(user()&&can('print'))echo '<div class="toolbar no-print"><button type="button" data-print>'.uiIcon('print').e(t('print')).'</button><span class="muted">'.e(fdate(date('Y-m-d')).' · '.t(cal()==='j'?'shamsi':'gregorian')).'</span></div>';
}
function pageEnd(): void {echo '<footer><span>'.e(setting('footer')).'</span><span class="print-only">'.e(t('signature')).' __________________ &nbsp; '.e(t('stamp')).' __________</span><span class="no-print">Khawar-Danish · 0.2 · '.e(t('offline')).'</span></footer></main></body></html>';}

function dateControl(string $id,string $name,string $value,string $mode='date',bool $required=true,?string $calendar=null): void {
 $calendar??=cal();$native=$calendar==='g';$today=Domain::displayDate(date('Y-m-d'),$calendar);
 echo '<input id="'.e($id).'" name="'.e($name).'" type="'.($native?$mode:'text').'" value="'.e($value).'"'.($required?' required':'').' data-date-picker data-calendar="'.$calendar.'" data-mode="'.$mode.'" data-today="'.e($today).'"'.($native?' min="1921-01'.($mode==='date'?'-01':'').'" max="2121-12'.($mode==='date'?'-31':'').'"':' readonly aria-haspopup="dialog"').' dir="ltr" autocomplete="off">';
 echo '<small>'.e(t($calendar==='j'?'shamsi':'gregorian')).'</small>';
}
